package id.pterobridge.client;
import org.bukkit.plugin.java.JavaPlugin; import java.io.*; import java.net.*; import java.util.*; import java.util.concurrent.*;
public final class MultiBridgeClient extends JavaPlugin {
 private static final byte[] MAGIC=new byte[]{'P','B','R','G'}; private volatile boolean running; private volatile DataOutputStream out; private final Object lock=new Object(); private final ConcurrentMap<Long,Socket> targets=new ConcurrentHashMap<>(); private final ExecutorService pool=Executors.newCachedThreadPool(r->{Thread t=new Thread(r,"PteroBridge-Mux-Client");t.setDaemon(true);return t;});
 @Override public void onEnable(){saveDefaultConfig();running=true;pool.execute(this::connectLoop);getLogger().info("Experimental multiplexed bridge client enabled.");}
 private void connectLoop(){String host=getConfig().getString("server-host","CHANGE_ME");int port=getConfig().getInt("gateway-port",10196);String route=getConfig().getString("public-address","");String token=getConfig().getString("token","");if(route.isBlank()||token.isBlank()){getLogger().severe("Set public-address and token in config.yml");return;}while(running){try(Socket s=new Socket()){s.connect(new InetSocketAddress(host,port),10000);s.setTcpNoDelay(true);DataInputStream in=new DataInputStream(s.getInputStream());DataOutputStream o=new DataOutputStream(new BufferedOutputStream(s.getOutputStream()));o.write(MAGIC);o.writeUTF(route);o.writeUTF(token);o.flush();synchronized(lock){out=o;}getLogger().info("Connected through shared route port "+port+" for "+route);readLoop(s,in);}catch(Exception e){if(running)getLogger().warning("Tunnel disconnected: "+e.getMessage()+"; retrying in 5 seconds.");}finally{synchronized(lock){out=null;}closeTargets();}try{Thread.sleep(5000);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}}
 private void readLoop(Socket s,DataInputStream in)throws IOException{while(running&&!s.isClosed()){byte type=in.readByte();long id=in.readLong();int len=in.readInt();if(len<0||len>1048576)throw new IOException("Invalid frame length");byte[] b=in.readNBytes(len);if(b.length!=len)throw new EOFException();if(type==1)openTarget(id);else if(type==4){Socket t=targets.get(id);if(t!=null)try{t.getOutputStream().write(b);t.getOutputStream().flush();}catch(IOException e){closeTarget(id);}}else if(type==5)closeTarget(id);}}
 private void openTarget(long id){getLogger().info("[MUX-DIAG] Opening local Paper target for player "+id);String host=getConfig().getString("target-host","127.0.0.1");int port=getConfig().getInt("target-port",25565);try{Socket t=new Socket();t.connect(new InetSocketAddress(host,port),10000);t.setTcpNoDelay(true);targets.put(id,t);getLogger().info("[MUX-DIAG] Local target connected for player "+id+" at "+host+":"+port);send((byte)2,id,new byte[0]);pool.execute(()->pump(id,t));}catch(IOException e){try{send((byte)3,id,new byte[0]);}catch(IOException ignored){}getLogger().warning("[MUX-DIAG] Cannot connect local target for player "+id+" at "+host+":"+port+": "+e.getMessage());}}
 private void pump(long id,Socket t){try(InputStream in=t.getInputStream()){byte[] b=new byte[8192];int n;while(running&&(n=in.read(b))!=-1)send((byte)4,id,Arrays.copyOf(b,n));}catch(IOException e){getLogger().warning("[MUX-DIAG] Local target stream ended for player "+id+": "+e.getMessage());}finally{targets.remove(id,t);try{send((byte)5,id,new byte[0]);}catch(IOException ignored){}try{t.close();}catch(IOException ignored){}}}
 private void send(byte type,long id,byte[] b)throws IOException{synchronized(lock){DataOutputStream o=out;if(o==null)throw new IOException("Tunnel not connected");o.writeByte(type);o.writeLong(id);o.writeInt(b.length);o.write(b);o.flush();}}
 private void closeTarget(long id){Socket t=targets.remove(id);if(t!=null)try{t.close();}catch(IOException ignored){}}private void closeTargets(){for(Long id:targets.keySet())closeTarget(id);}
 @Override public void onDisable(){running=false;closeTargets();pool.shutdownNow();}
}
